def record(word, counts=None):
    if counts is None:
        counts = {}
    counts[word] = counts.get(word, 0) + 1
    return counts

print(record("A"))
print(record("B"))
totals = {}
record("A", totals)
record("A", totals)
print(totals)

def select_scores(scores, minimum):
    selected = []
    for score in scores:
        if score >= minimum:
            selected.append(score)
    return selected

def average(values):
    if not values:
        return None
    total = 0
    for value in values:
        total += value
    return total / len(values)

scores = [40, 80, 100]
selected = select_scores(scores, 60)
print(average(selected))
selected = select_scores(scores, 101)
result = average(selected)
if result is None:
    print("대상 없음")
else:
    print(result)
